"use strict";
// describe's Uint8Array specialization reaches a form only the checked-
// dynamic body lowers (JSON.stringify of a typed array), so that instance
// forwards to the checked-dynamic one; the string specialization stands.
function describe(view, label) {
  return label + "=" + JSON.stringify(view) + "/" + view.length;
}
function run() {
  return [describe(new Uint8Array([1, 2]), "v"), describe("str", "s"), describe([3], "a")].join(" ");
}
module.exports = { run: run };
